import wordfreq
from wordfreq import top_words


def run(content, *args, raw=None):
    with tempfile.NamedTemporaryFile(delete=False, dir='.') as f:
        f.write(raw if raw is not None else content.encode('utf-8'))
    try:
        p = subprocess.run([sys.executable, 'wordfreq.py', f.name, *args], capture_output=True)
    finally:
        os.unlink(f.name)
    return p.returncode, p.stdout.decode('utf-8'), p.stderr.decode('utf-8')


class T(unittest.TestCase):
    def test_case(self): self.assertEqual(top_words("The THE the don't 'tis"), [("the", 3), ("don't", 1), ("tis", 1)])
    def test_empty(self): self.assertEqual(top_words(""), [])
    def test_ties(self): self.assertEqual(top_words("c b a b c c", n=2), [("c", 3), ("b", 2)])
    def test_minlen(self): self.assertEqual(top_words("a bb ccc", min_length=2), [("bb", 1), ("ccc", 1)])
    def test_minlen_strip(self): self.assertEqual(top_words("'ab' abc", min_length=3), [("abc", 1)])
    def test_underscore(self): self.assertEqual(top_words("snake_case"), [("case", 1), ("snake", 1)])
    def test_apos(self): self.assertEqual(top_words("'''x''' '' a''b a''b"), [("a''b", 2), ("x", 1)])
    def test_unicode(self): self.assertEqual(top_words("Ωmega ωMEGA café CAFÉ"), [("café", 2), ("ωmega", 2)])
    def test_digits(self): self.assertEqual(top_words("42 042 42"), [("42", 2), ("042", 1)])

    def test_nfd(self):
        r = top_words("cafe\u0301")
        self.assertEqual(len(r), 1)
        self.assertEqual(r[0][1], 1)

    def test_default_n(self):
        self.assertEqual([w for w, _ in top_words("a b c d e f g h i j k l")], list("abcdefghij"))

    def test_bad_n(self):
        with self.assertRaises(ValueError):
            top_words("a", n=0)

    def test_types(self):
        r = top_words("a b a")
        self.assertIsInstance(r, list)
        self.assertIsInstance(r[0], tuple)

    def test_cli_format(self): self.assertEqual(run("a a b"), (0, "a\t2\nb\t1\n", ""))

    def test_cli_missing(self):
        p = subprocess.run([sys.executable, 'wordfreq.py', 'no_such_file_xyz.txt'], capture_output=True, text=True)
        self.assertEqual(p.returncode, 2)
        self.assertEqual(p.stdout, "")
        self.assertIn("error", p.stderr)

    def test_cli_n0(self): self.assertEqual(run("a", "-n", "0")[0], 2)
    def test_cli_nneg(self): self.assertEqual(run("a", "-n", "-1")[0], 2)
    def test_cli_empty(self): self.assertEqual(run(""), (0, "", ""))
    def test_cli_opts(self): self.assertEqual(run("aa aa bb c c c dd", "-n", "2", "--min-length", "2")[1], "aa\t2\nbb\t1\n")
    def test_cli_badutf8(self): self.assertEqual(run("", raw=b"\xff\xfe\xfa")[0], 2)
    def test_cli_utf8_out(self): self.assertEqual(run("café Café")[1], "café\t2\n")
    def test_import_quiet(self): self.assertTrue(callable(wordfreq.main))


unittest.main(verbosity=1)
